package com.whaa.shop.user.application;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.whaa.shop.common.exception.BusinessException;import com.whaa.shop.common.security.CurrentUser;import com.whaa.shop.user.domain.User;import com.whaa.shop.user.infrastructure.UserMapper;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.Locale;
@Service public class UserAdminService {private final UserMapper users;private final PasswordEncoder encoder;private final JdbcTemplate jdbc;public UserAdminService(UserMapper users,PasswordEncoder encoder,JdbcTemplate jdbc){this.users=users;this.encoder=encoder;this.jdbc=jdbc;}
 @Transactional public User create(String username,String email,String password,String nickname,String role,boolean enabled){String account=username.trim(),mail=normalizeEmail(email);if(users.selectCount(new LambdaQueryWrapper<User>().eq(User::getUsername,account))>0)throw new BusinessException("用户名已存在");ensureEmailAvailable(mail,null);if(!"ADMIN".equals(role)&&!"USER".equals(role))throw new BusinessException("角色无效");User user=new User();user.setUsername(account);user.setEmail(mail);user.setPasswordHash(encoder.encode(password));user.setNickname(nickname.trim());user.setRole(role);user.setEnabled(enabled);user.setCreatedAt(LocalDateTime.now());users.insert(user);return user;}
 @Transactional public User update(Long id,String username,String email,String password,String nickname,String role,boolean enabled){User user=users.selectById(id);if(user==null)throw new BusinessException("用户不存在");String account=username.trim(),mail=normalizeEmail(email);if(users.selectCount(new LambdaQueryWrapper<User>().eq(User::getUsername,account).ne(User::getId,id))>0)throw new BusinessException("用户名已存在");ensureEmailAvailable(mail,id);if(!"ADMIN".equals(role)&&!"USER".equals(role))throw new BusinessException("角色无效");user.setUsername(account);user.setEmail(mail);user.setNickname(nickname.trim());user.setRole(role);user.setEnabled(enabled);if(password!=null&&!password.isBlank()){if(password.length()<6||password.length()>64)throw new BusinessException("新密码长度需为 6-64 个字符");user.setPasswordHash(encoder.encode(password));}users.updateById(user);return user;}
 @Transactional public void delete(Long id){User user=users.selectById(id);if(user==null)throw new BusinessException("用户不存在");if(CurrentUser.id()==id)throw new BusinessException("不能删除当前登录的管理员");if("ADMIN".equals(user.getRole())&&users.selectCount(new LambdaQueryWrapper<User>().eq(User::getRole,"ADMIN"))<=1)throw new BusinessException("系统至少需要保留一个管理员");Long references=jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM user_address WHERE user_id=?)+(SELECT COUNT(*) FROM cart_item WHERE user_id=?)+(SELECT COUNT(*) FROM shop_order WHERE user_id=?)+(SELECT COUNT(*) FROM product_review WHERE user_id=?)+(SELECT COUNT(*) FROM knowledge_file WHERE uploaded_by=?)",Long.class,id,id,id,id,id);if(references!=null&&references>0)throw new BusinessException("该用户已产生业务数据，为保留订单和审计记录，请改为禁用用户");users.deleteById(id);}private String normalizeEmail(String email){if(email==null||email.isBlank())throw new BusinessException("请输入邮箱");return email.trim().toLowerCase(Locale.ROOT);}private void ensureEmailAvailable(String email,Long excludedId){var q=new LambdaQueryWrapper<User>().eq(User::getEmail,email).ne(excludedId!=null,User::getId,excludedId);if(users.selectCount(q)>0)throw new BusinessException("邮箱已被使用");}}
